export default function Files() {
  return (
    <div className="p-6 max-w-5xl mx-auto bg-white rounded shadow">
      <h2 className="text-xl font-bold mb-4">Your Files</h2>
      <FileRow name="document.pdf" size="2 MB" />
      <FileRow name="photo.jpg" size="1.5 MB" />
    </div>
  );
}
